actions.script:
const pref = (key) => { const value = ec.user.getPreference(key); return value == null || String(value).trim() === '' ? null : String(value).trim() }
const flag = (key, fallback) => { const value = pref(key); return value == null ? fallback : (value === 'Y' || value === 'true') }
const L = (text) => ec.l10n.localize(text)
let presets = null
try { presets = JSON.parse(pref('CHAT_STATUS_PRESETS') || 'null') } catch (err) { presets = null }
if (!Array.isArray(presets)) presets = [{emoji: '📅', text: L('In a meeting'), clearAfter: '60'}, {emoji: '🚌', text: L('Commuting'), clearAfter: '30'},
    {emoji: '🤒', text: L('Out sick'), clearAfter: 'today'}, {emoji: '🏠', text: L('Working remotely'), clearAfter: 'today'},
    {emoji: '🌴', text: L('On vacation'), clearAfter: '0'}]
const level = pref('CHAT_NOTIFY_DEFAULT')
const minutes = Number(pref('CHAT_AUTO_AWAY_MINUTES'))
prefs = {enterSends: flag('CHAT_ENTER_SENDS', true), sounds: flag('CHAT_SOUNDS', true), readReceipts: flag('CHAT_READ_RECEIPTS', true),
    typing: flag('CHAT_TYPING', true), linkPreviews: flag('CHAT_LINK_PREVIEWS', true), notifyDefault: ['all', 'mentions', 'none'].includes(level) ? level : '', notifyPreview: flag('CHAT_NOTIFY_PREVIEW', true),
    autoAwayMinutes: minutes > 0 ? minutes : 10, dndFrom: pref('CHAT_DND_FROM'), dndTo: pref('CHAT_DND_TO'),
    statusPresets: presets.filter((item) => item && (item.text || item.emoji)).slice(0, 12).map((item) => ({emoji: String(item.emoji || ''),
        text: String(item.text || ''), clearAfter: String(item.clearAfter ?? '0')}))}

const yn = (value) => value === 'Y' || value === 'true' || value === true ? 'Y' : 'N'
if (saveFlags) {
    ec.user.setPreference('CHAT_ENTER_SENDS', yn(enterSends))
    ec.user.setPreference('CHAT_SOUNDS', yn(sounds))
    ec.user.setPreference('CHAT_READ_RECEIPTS', yn(readReceipts))
    ec.user.setPreference('CHAT_TYPING', yn(typing))
    ec.user.setPreference('CHAT_LINK_PREVIEWS', yn(linkPreviews))
    ec.user.setPreference('CHAT_NOTIFY_PREVIEW', yn(notifyPreview))
} else {
    if (enterSends != null) ec.user.setPreference('CHAT_ENTER_SENDS', yn(enterSends))
    if (sounds != null) ec.user.setPreference('CHAT_SOUNDS', yn(sounds))
    if (readReceipts != null) ec.user.setPreference('CHAT_READ_RECEIPTS', yn(readReceipts))
    if (typing != null) ec.user.setPreference('CHAT_TYPING', yn(typing))
    if (linkPreviews != null) ec.user.setPreference('CHAT_LINK_PREVIEWS', yn(linkPreviews))
    if (notifyPreview != null) ec.user.setPreference('CHAT_NOTIFY_PREVIEW', yn(notifyPreview))
}
if (notifyDefault != null) {
    if (!['', 'all', 'mentions', 'none'].includes(String(notifyDefault))) { ec.message.addError(ec.l10n.localize('Choose all, mentions or nothing')); return }
    ec.user.setPreference('CHAT_NOTIFY_DEFAULT', String(notifyDefault))
}
if (autoAwayMinutes != null && String(autoAwayMinutes) !== '') {
    const minutes = Number(autoAwayMinutes)
    if (!(minutes >= 1 && minutes <= 480)) { ec.message.addError(ec.l10n.localize('Away after 1 to 480 minutes')); return }
    ec.user.setPreference('CHAT_AUTO_AWAY_MINUTES', String(Math.round(minutes)))
}
if (saveDnd) {
    const hhmm = (value) => {
        const text = String(value || '').trim()
        const match = /^(\d{1,2}):(\d{2})/.exec(text)
        if (!match || Number(match[1]) > 23 || Number(match[2]) > 59) return null
        return String(match[1]).padStart(2, '0') + ':' + match[2]
    }
    const from = hhmm(dndFrom), to = hhmm(dndTo)
    if ((dndFrom || dndTo) && !(from && to)) { ec.message.addError(ec.l10n.localize('Give both times of the do not disturb hours, or neither')); return }
    if (from && to && from === to) { ec.message.addError(ec.l10n.localize('The do not disturb hours end when they start')); return }
    ec.user.setPreference('CHAT_DND_FROM', from || '')
    ec.user.setPreference('CHAT_DND_TO', to || '')
}

const current = ec.service.sync().name('org.moqui.comms.ChatScreenServices.get#ChatPrefs').call().prefs.statusPresets
const list = Array.from(current || [])
if (action === 'add') {
    const shownText = String(text || '').trim(), shownEmoji = String(emoji || '').trim()
    if (!shownText && !shownEmoji) { ec.message.addError(ec.l10n.localize('A status needs a text or an emoji')); return }
    if (Array.from(shownText).length > 100) { ec.message.addError(ec.l10n.localize('A status is up to 100 characters')); return }
    if (Array.from(shownEmoji).length > 16 || /[<>]/.test(shownEmoji)) { ec.message.addError(ec.l10n.localize('An emoji is a few characters')); return }
    if (list.length >= 12) { ec.message.addError(ec.l10n.localize('Twelve presets at most')); return }
    const clear = ['0', '30', '60', '240', 'today', 'week'].includes(String(clearAfter || '0')) ? String(clearAfter || '0') : '0'
    list.push({emoji: shownEmoji, text: shownText, clearAfter: clear})
} else if (action === 'remove') {
    if (index == null || index < 0 || index >= list.length) { ec.message.addError(ec.l10n.localize('No such preset')); return }
    list.splice(index, 1)
} else { ec.message.addError(`Unknown action ${action}`); return }
ec.user.setPreference('CHAT_STATUS_PRESETS', JSON.stringify(list))
statusPresets = list

const presets = Array.from(ec.service.sync().name('org.moqui.comms.ChatScreenServices.get#ChatPrefs').call().prefs.statusPresets || [])
const preset = index != null && index >= 0 ? presets[index] : null
if (!preset) { ec.message.addError(ec.l10n.localize('No such preset')); return }
const params = {statusText: preset.text || '', emoji: preset.emoji || ''}
const clear = String(preset.clearAfter || '0')
if (/^\d+$/.test(clear)) params.clearAfterMinutes = Number(clear)
else {
    // the end of the user's day, or of the week's Sunday: the date in the user's zone, then its last second there
    const today = String(ec.l10n.format(ec.user.nowTimestamp, 'yyyy-MM-dd'))
    const [year, month, day] = today.split('-').map(Number)
    const civil = new Date(Date.UTC(year, month - 1, day))
    if (clear === 'week') civil.setUTCDate(civil.getUTCDate() + (7 - civil.getUTCDay()) % 7)
    const last = civil.getUTCFullYear() + '-' + String(civil.getUTCMonth() + 1).padStart(2, '0') + '-' + String(civil.getUTCDate()).padStart(2, '0')
    params.clearAtDate = ec.l10n.parseTimestamp(last + ' 23:59:59', 'yyyy-MM-dd HH:mm:ss')
}
const out = ec.service.sync().name('org.moqui.impl.ChatServices.set#UserStatus').parameters(params).call()
if (!ec.message.hasError()) myStatus = out.myStatus

updatedCount = 0; failedCount = 0
const LEVELS = {all: 'CnlAll', mentions: 'CnlMentions', none: 'CnlNone'}
const level = String(ec.user.getPreference('CHAT_NOTIFY_DEFAULT') || '').trim()
if (!LEVELS[level]) { ec.message.addError(ec.l10n.localize('Choose a default notification level first')); return }
const rooms = ec.service.sync().name('org.moqui.impl.ChatServices.find#Rooms').parameter('limit', 1000).call()
if (ec.message.hasError()) return
for (const room of Array.from(rooms.roomList || [])) {
    if (!room.isMember || room.roomTypeEnumId === 'CrtDirect' || room.notificationLevelEnumId === LEVELS[level]) continue
    ec.message.pushErrors()
    try {
        ec.service.sync().name('org.moqui.impl.ChatServices.set#Notification').parameters({chatRoomId: room.chatRoomId,
            notificationLevelEnumId: level}).requireNewTransaction(true).call()
        if (ec.message.hasError()) { failedCount++; ec.logger.warn(`Chat: notification level not set on room ${room.chatRoomId}: ${ec.message.errorsString}`) }
        else updatedCount++
    } catch (err) {
        failedCount++
        ec.logger.warn(`Chat: notification level not set on room ${room.chatRoomId}: ${err && err.message ? err.message : err}`)
    } finally { ec.message.clearErrors(); ec.message.popErrors() }
}

dndCount = 0; backCount = 0
const toMinutes = (text) => { const match = /^(\d{1,2}):(\d{2})$/.exec(String(text || '').trim()); return match ? Number(match[1]) * 60 + Number(match[2]) : null }
const users = {}
for (const row of ec.entity.find('moqui.security.UserPreference').condition('preferenceKey', 'in', ['CHAT_DND_FROM', 'CHAT_DND_TO', 'CHAT_DND_AUTO'])
        .disableAuthz().list()) (users[row.userId] = users[row.userId] || {})[row.preferenceKey] = row.preferenceValue
const wasDisabled = ec.artifactExecution.disableAuthz()
try {
    for (const userId of Object.keys(users)) {
        const prefs = users[userId]
        const auto = prefs.CHAT_DND_AUTO === 'Y'
        const from = toMinutes(prefs.CHAT_DND_FROM), to = toMinutes(prefs.CHAT_DND_TO)
        if (!auto && (from == null || to == null)) continue
        ec.message.pushErrors()
        try {
            const account = ec.entity.find('moqui.security.UserAccount').condition('userId', userId).one()
            if (!account || account.disabled === 'Y') continue
            // the user's local time: the time zone of this run is the user's for the formatting
            ec.user.setTimeZone(account.timeZone || null)
            const now = toMinutes(ec.l10n.format(ec.user.nowTimestamp, 'HH:mm'))
            const inside = from != null && to != null && from !== to && (from < to ? (now >= from && now < to) : (now >= from || now < to))
            const status = ec.entity.find('moqui.security.UserStatus').condition('userId', userId).one()
            const statusId = status ? (status.statusEnumId || 'UpsOnline') : 'UpsOnline'
            const setAuto = (value) => {
                const row = ec.entity.makeValue('moqui.security.UserPreference')
                row.setFields({userId: userId, preferenceKey: 'CHAT_DND_AUTO', preferenceValue: value}, true, null, null)
                row.createOrUpdate()
            }
            if (inside && !auto && statusId === 'UpsOnline') {
                ec.service.sync().name('org.moqui.impl.ChatServices.set#UserStatus').parameters({userId: userId, status: 'dnd'}).requireNewTransaction(true).call()
                if (!ec.message.hasError()) { setAuto('Y'); dndCount++ }
            } else if (!inside && auto) {
                if (statusId === 'UpsDnd') ec.service.sync().name('org.moqui.impl.ChatServices.set#UserStatus').parameters({userId: userId, status: 'online'})
                        .requireNewTransaction(true).call()
                if (!ec.message.hasError()) { setAuto('N'); backCount++ }
            }
            if (ec.message.hasError()) ec.logger.error(`Chat do not disturb hours of user ${userId} not applied: ${ec.message.errorsString}`)
        } catch (err) {
            ec.logger.error(`Chat do not disturb hours of user ${userId} not applied: ${err && err.message ? err.message : err}`)
        } finally { ec.message.clearErrors(); ec.message.popErrors() }
    }
} finally {
    ec.user.setTimeZone(null)
    if (!wasDisabled) ec.artifactExecution.enableAuthz()
}

const appRoot = System.getProperty('comms_app_root') || '/qapps/BasicComms'
const rooms = Array.from(roomList || [])
const wanted = rooms.filter((room) => room.recordEntityName && room.recordId)
        .map((room) => ({recordEntityName: room.recordEntityName, recordId: room.recordId}))
const found = {}
if (wanted.length) {
    const out = ec.service.sync().name('org.moqui.comms.ChatScreenServices.lookup#Records').parameters({operation: 'info', records: wanted}).call()
    for (const info of Array.from(out?.recordList || [])) found[info.recordEntityName + '|' + info.recordId] = info
}
roomList = rooms.map((source) => {
    const room = Object.assign({}, source)
    room.url = appRoot + '/Chat?chatRoomId=' + encodeURIComponent(room.chatRoomId)
    room.record = null
    if (room.recordEntityName && room.recordId) {
        const info = found[room.recordEntityName + '|' + room.recordId]
        room.record = info && info.visible ? {visible: true, title: info.title, typeLabel: info.typeLabel || null, url: info.url || null,
            icon: info.icon || 'sym_o_description', entity: info.entity || room.recordEntityName, id: room.recordId}
            : {visible: false, title: room.roomName || room.recordId, typeLabel: null, url: null, icon: 'sym_o_description',
                entity: room.recordEntityName, id: room.recordId}
    }
    return room
})

const account = ec.user.userAccount || {}
me = {userId: ec.user.userId, username: ec.user.username, name: account.userFullName || ec.user.username, partyId: account.partyId || null}
prefs = ec.service.sync().name('org.moqui.comms.ChatScreenServices.get#ChatPrefs').call().prefs
// File on a record is offered only with an app that files messages on its records (a record-link provider)
const linkers = ec.service.sync().name('org.moqui.impl.ShellServices.get#Providers').parameter('hook', 'record-link').call()
prefs.recordLink = Array.from(linkers?.providerList || []).length > 0
const out = ec.service.sync().name('org.moqui.impl.ChatServices.find#Rooms').parameter('limit', Math.max(1, Math.min(limit || 200, 500))).call()
if (ec.message.hasError()) return
roomList = ec.service.sync().name('org.moqui.comms.ChatScreenServices.decorate#Rooms').parameter('roomList', out.roomList).call().roomList
unreadTotal = out.unreadTotal
mentionTotal = out.mentionTotal

const out = ec.service.sync().name('org.moqui.impl.ChatServices.find#Rooms').parameters({filter: filter || null, searchText: searchText || null,
    includeJoinable: includeJoinable || joinableOnly, limit: Math.max(1, Math.min(limit || 200, 500))}).call()
if (ec.message.hasError()) return
let list = Array.from(out.roomList || [])
if (joinableOnly) list = list.filter((room) => !room.isMember)
roomList = ec.service.sync().name('org.moqui.comms.ChatScreenServices.decorate#Rooms').parameter('roomList', list).call().roomList

const out = ec.service.sync().name('org.moqui.impl.ChatServices.get#Room').parameter('chatRoomId', chatRoomId).call()
if (ec.message.hasError() || !out.room) return
member = out.member; access = out.access; memberList = out.memberList
const source = Object.assign({}, out.room)
const me = ec.user.userId
if (!source.roomName) {
    const others = Array.from(memberList || []).filter((item) => item.userId !== me).map((item) => item.name)
    source.displayName = others.length ? others.join(', ') : (Array.from(memberList || []).find((item) => item.userId === me) || {}).name || chatRoomId
} else source.displayName = source.roomName
const otherIds = Array.from(memberList || []).filter((item) => item.userId && item.userId !== me).map((item) => item.userId)
source.otherUserIdList = source.roomTypeEnumId === 'CrtDirect' ? otherIds : []
source.otherUserId = source.roomTypeEnumId === 'CrtDirect' && otherIds.length === 1 ? otherIds[0] : null
room = ec.service.sync().name('org.moqui.comms.ChatScreenServices.decorate#Rooms').parameter('roomList', [source]).call().roomList[0]
timeline = ec.service.sync().name('org.moqui.comms.ChatScreenServices.get#TimelinePage').parameters({chatRoomId: chatRoomId, aroundSeq: aroundSeq ?? null,
    limit: limit}).call().page

const out = ec.service.sync().name('org.moqui.impl.ChatServices.get#Timeline').parameters({chatRoomId: chatRoomId, beforeSeq: beforeSeq ?? null,
    afterSeq: afterSeq ?? null, aroundSeq: aroundSeq ?? null, threadRootEventSeq: threadRootEventSeq ?? null, pinnedOnly: !!pinnedOnly,
    eventSeq: eventSeq ?? null, limit: Math.max(1, Math.min(limit || 50, 200))}).call()
if (ec.message.hasError()) return
const events = Array.from(out.eventList || [])
const ids = new Set()
for (const event of events) {
    if (event.senderUserId) ids.add(event.senderUserId)
    const content = event.content || {}
    for (const key of ['userId', 'byUserId']) if (content[key]) ids.add(String(content[key]))
    for (const id of Array.from(content.userIds || [])) ids.add(String(id))
    for (const reaction of Array.from(event.reactions || [])) for (const id of Array.from(reaction.userIds || [])) ids.add(String(id))
    if (event.replyTo && event.replyTo.senderUserId) ids.add(event.replyTo.senderUserId)
    if (event.threadLastUserId) ids.add(event.threadLastUserId)
    if (event.forwardOf && event.forwardOf.senderUserId) ids.add(event.forwardOf.senderUserId)
    if (event.poll) for (const option of Array.from(event.poll.options || [])) for (const id of Array.from(option.voterIds || [])) ids.add(String(id))
}
const userNames = {}
if (ids.size) for (const account of ec.entity.find('moqui.security.UserAccount').condition('userId', 'in', Array.from(ids))
        .selectField('userId').selectField('userFullName').selectField('username').disableAuthz().list())
    userNames[account.userId] = account.userFullName || account.username || account.userId
// the external actors of a bridged room (a reaction's, a membership's): their names on their networks
const actorIds = Array.from(ids).filter((id) => !userNames[id])
for (const event of events) if (event.content && event.content.chatActorId) actorIds.push(String(event.content.chatActorId))
if (actorIds.length) {
    const actors = ec.service.sync().name('org.moqui.impl.ChatServices.get#ActorNames').parameter('chatActorIdList', actorIds).call()?.actorMap || {}
    for (const [id, actor] of Object.entries(actors)) userNames[id] = actor.name
}
page = {room: out.room, access: out.access, eventList: events, hasMoreBefore: !!out.hasMoreBefore, hasMoreAfter: !!out.hasMoreAfter,
    lastReadEventSeq: out.lastReadEventSeq, memberList: out.memberList, userNames: userNames}

userList = []
const me = ec.user.userId
const text = String(term || '').trim().toLowerCase()
const max = Math.max(1, Math.min(limit || 10, 25))
// get#RoomAccess adds no error for a room the user may not read (an error would mark the transaction rollback-only)
const access = ec.service.sync().name('org.moqui.impl.ChatServices.get#RoomAccess').parameter('chatRoomId', chatRoomId).call()
if (ec.message.hasError() || !access || !access.canRead) return
const out = ec.service.sync().name('org.moqui.impl.ChatServices.get#Room').parameter('chatRoomId', chatRoomId).call()
if (ec.message.hasError() || !out || !out.room) return
const everyone = Array.from(out.memberList || []).filter((member) => !member.isAgent)
if ((access.canModerate || access.isOwner || everyone.length <= 20) && (!text || 'room'.startsWith(text) || 'everyone'.startsWith(text)))
    userList.push({id: '@room', label: 'room'})
for (const member of Array.from(out.memberList || [])) {
    if (!member.userId || member.userId === me || member.isAgent) continue
    if (text && !String(member.name || '').toLowerCase().includes(text)) continue
    userList.push({id: member.userId, label: member.name})
}
if (out.room.visibilityEnumId === 'CrvUsers' && userList.length < max) {
    const found = ec.service.sync().name('org.moqui.comms.CommsServices.search#Users').parameters({term: text, limit: max}).call()
    for (const user of Array.from(found.userList || [])) {
        if (user.id === me || userList.some((item) => item.id === user.id)) continue
        userList.push({id: user.id, label: user.label})
    }
}
userList = userList.slice(0, max)

const TYPES = {direct: 'CrtDirect', private: 'CrtPrivate', public: 'CrtPublic'}
const type = TYPES[roomTypeEnumId] || roomTypeEnumId
if (!Object.values(TYPES).includes(type)) { ec.message.addError(ec.l10n.localize('A room is direct, private or public')); return }
const ids = Array.from(memberUserIdList || []).concat(memberUserIds ? String(memberUserIds).split(',') : [])
        .map((id) => String(id || '').trim()).filter((id) => id)
if (type === 'CrtDirect' && !ids.length) { ec.message.addError(ec.l10n.localize('Choose who to message')); return }
const out = ec.service.sync().name('org.moqui.impl.ChatServices.create#Room').parameters({roomTypeEnumId: type, roomName: roomName || null,
    topic: topic || null, memberUserIdList: Array.from(new Set(ids))}).call()
if (ec.message.hasError()) return
chatRoomId = out.chatRoomId
created = !!out.created

created = false
const looked = ec.service.sync().name('org.moqui.comms.ChatScreenServices.lookup#Records').parameters({operation: 'info',
    records: [{recordEntityName: recordEntityName, recordId: recordId}]}).call()
const info = Array.from(looked?.recordList || [])[0] || null
const entityName = info && info.visible && info.entity ? info.entity : recordEntityName
const existing = ec.service.sync().name('org.moqui.impl.ChatServices.get#Room').parameters({recordEntityName: entityName, recordId: recordId}).call()
if (ec.message.hasError()) return
if (existing.room) { chatRoomId = existing.room.chatRoomId; return }
if (info && !info.visible) { ec.message.addError(ec.resource.expand('Record ${entity} ${id} not found', '', {entity: recordEntityName, id: recordId})); return }
const made = ec.service.sync().name('org.moqui.impl.ChatServices.create#Room').parameters({roomTypeEnumId: 'CrtRecord',
    recordEntityName: entityName, recordId: recordId, roomName: (info && info.title) || recordId}).call()
if (ec.message.hasError()) return
chatRoomId = made.chatRoomId
created = !!made.created

service.description:
Internal: what the apps' record-lookup providers answer (org.moqui.impl.ShellServices.call#Providers,
            hook record-lookup), combined:
            - info: for records [{recordEntityName, recordId}], recordList [{recordEntityName, recordId, entity (the full
              name), visible, title, typeLabel, url, icon}], the first provider's answer for each record;
            - card: for recordEntityName and recordId, the record card (m-record-card) of the first provider with one;
            - search: for text, optionList [{value (entity|id), label}] of every provider, in their order, up to 20;
            - links: for body (a message's HTML), recordList [{entity, id}], the records its links name, up to five.
            A provider that fails is left out (logged by call#Providers); with none, the answers are empty.

actions.script:
recordList = []
optionList = []
card = null
if (!['info', 'card', 'search', 'links'].includes(operation)) { ec.message.addError('Unknown record lookup ' + operation); return }
const out = ec.service.sync().name('org.moqui.impl.ShellServices.call#Providers').parameters({hook: 'record-lookup',
    parameters: {operation: operation, records: records || null, recordEntityName: recordEntityName || null, recordId: recordId || null,
        text: text || null, body: body || null}}).call()
const results = Array.from(out?.results || [])
if (operation === 'info') {
    const seen = new Set()
    for (const result of results) for (const info of Array.from(result.recordList || [])) {
        const key = info.recordEntityName + '|' + info.recordId
        if (seen.has(key)) continue
        seen.add(key)
        recordList.push(info)
    }
} else if (operation === 'card') {
    card = results.map((result) => result.card).find((found) => found && Object.keys(found).length) || null
} else if (operation === 'search') {
    for (const result of results) for (const option of Array.from(result.optionList || [])) if (optionList.length < 20) optionList.push(option)
} else {
    const seen = new Set()
    for (const result of results) for (const record of Array.from(result.recordList || [])) {
        const key = record.entity + '|' + record.id
        if (seen.has(key) || recordList.length >= 5) continue
        seen.add(key)
        recordList.push({entity: record.entity, id: record.id})
    }
}

uploadList = []; failedList = []
const files = (Array.isArray(file) ? file : [file]).filter((item) => item != null && typeof item === 'object')
if (!files.length) { ec.message.addError(ec.l10n.localize('No file uploaded')); return }
for (const item of files) {
    const name = String(item.name || item.fileName || 'file')
    ec.message.pushErrors()
    try {
        const out = ec.service.sync().name('org.moqui.impl.ChatServices.upload#Attachment').parameters({chatRoomId: chatRoomId, file: item})
                .requireNewTransaction(true).call()
        if (ec.message.hasError()) failedList.push({fileName: name, error: ec.message.errorsString})
        else uploadList.push({chatAttachmentId: out.chatAttachmentId, fileName: out.fileName, contentType: out.contentType, fileSize: out.fileSize})
    } catch (err) {
        failedList.push({fileName: name, error: err && err.message ? err.message : String(err)})
    } finally { ec.message.clearErrors(); ec.message.popErrors() }
}
for (const failed of failedList) ec.logger.warn(`Chat: file ${failed.fileName} not stored in room ${chatRoomId}: ${failed.error}`)
if (!uploadList.length && failedList.length) ec.message.addError(failedList[0].error)

rows = []
moreUrl = (System.getProperty('comms_app_root') || '/qapps/BasicComms') + '/Chat'
const L = (text) => ec.l10n.localize(text)
const term = String(text || '').replace(/^#/, '').trim()
const max = Math.max(1, Math.min(limit || 5, 20))
ec.message.pushErrors()
try {
    const out = ec.service.sync().name('org.moqui.impl.ChatServices.find#Rooms').parameters({searchText: term || null, includeJoinable: true,
        limit: max}).call()
    if (ec.message.hasError()) { ec.logger.warn(`Palette chat rooms for ${term} failed: ${ec.message.errorsString}`); return }
    const kinds = {CrtDirect: ['sym_o_person', 'Direct message'], CrtPrivate: ['sym_o_lock', 'Private room'], CrtPublic: ['sym_o_tag', 'Public room'],
        CrtRecord: ['sym_o_description', 'Record room']}
    for (const room of Array.from(out.roomList || [])) {
        const kind = kinds[room.roomTypeEnumId] || ['sym_o_chat', 'Room']
        const parts = [L(kind[1])]
        if (!room.isMember) parts.push(L('not joined'))
        if (room.unreadCount) parts.push(ec.resource.expand('${count} unread', '', {count: room.unreadCount}))
        if (room.topic) parts.push(room.topic)
        rows.push({title: room.displayName, subtitle: parts.join(' · '), icon: kind[0],
            url: (System.getProperty('comms_app_root') || '/qapps/BasicComms') + '/Chat?chatRoomId=' + encodeURIComponent(room.chatRoomId)})
    }
} catch (err) {
    ec.logger.warn(`Palette chat rooms for ${term} failed: ${err && err.message ? err.message : err}`)
} finally { ec.message.clearErrors(); ec.message.popErrors() }
